-- Directory RPCs are publicly callable. Bound their input and result sets so a
-- broad map query cannot turn into an unbounded PostGIS scan or response.
drop function public.nearby_shops(double precision, double precision, integer, text, text, integer, uuid, uuid);
drop function public.shops_by_location(text, text, text, integer, uuid, uuid);

create function public.nearby_shops(search_latitude double precision, search_longitude double precision, radius_miles integer default 25, vehicle_make text default null, vehicle_model text default null, vehicle_year integer default null, capability_filter uuid default null, partner_type_filter uuid default null, result_limit integer default 50, result_offset integer default 0)
returns table (id uuid, name text, city text, state text, distance_miles numeric, description text, address text, website text, phone text, email text, hours text, service_territory text, partner_type text, makes text[], models text[], model_years integer[], services text[], certifications text[], average_rating numeric, review_count bigint)
language plpgsql stable security definer set search_path = public as $$
begin
  if search_latitude is null or search_latitude < -90 or search_latitude > 90 or search_longitude is null or search_longitude < -180 or search_longitude > 180 then raise exception 'Search coordinates are invalid' using errcode = '22023'; end if;
  if radius_miles is null or radius_miles not between 1 and 200 then raise exception 'Search radius must be between 1 and 200 miles' using errcode = '22023'; end if;
  if result_limit is null or result_limit not between 1 and 100 or result_offset is null or result_offset not between 0 and 10000 then raise exception 'Pagination is outside the allowed range' using errcode = '22023'; end if;
  if length(coalesce(vehicle_make, '')) > 120 or length(coalesce(vehicle_model, '')) > 120 or (vehicle_year is not null and vehicle_year not between 1886 and 2100) then raise exception 'Directory filters are invalid' using errcode = '22023'; end if;

  return query with origin as (select st_setsrid(st_makepoint(search_longitude, search_latitude), 4326)::geography as point)
  select shop.id, shop.name, shop.city, shop.state, round((st_distance(st_setsrid(st_makepoint(shop.longitude, shop.latitude), 4326)::geography, origin.point) / 1609.344)::numeric, 1), shop.description, shop.address, shop.website, shop.phone, shop.email, shop.hours, shop.service_territory, type.name,
    coalesce((select array_agg(distinct vehicle.make order by vehicle.make) from shop_vehicles supported join vehicle_catalog vehicle on vehicle.id = supported.vehicle_id where supported.shop_id = shop.id), '{}'), coalesce((select array_agg(distinct vehicle.model order by vehicle.model) from shop_vehicles supported join vehicle_catalog vehicle on vehicle.id = supported.vehicle_id where supported.shop_id = shop.id), '{}'), coalesce((select array_agg(distinct vehicle.model_year order by vehicle.model_year) from shop_vehicles supported join vehicle_catalog vehicle on vehicle.id = supported.vehicle_id where supported.shop_id = shop.id), '{}'), coalesce((select array_agg(capability.name order by capability.name) from partner_capabilities assigned join service_capabilities capability on capability.id = assigned.capability_id and capability.active where assigned.shop_id = shop.id), '{}'), coalesce((select array_agg(certification.name order by certification.name) from shop_certifications assigned join certifications certification on certification.id = assigned.certification_id and certification.is_active where assigned.shop_id = shop.id), '{}'), reviews.average_rating, coalesce(reviews.review_count, 0)
  from shops shop join partner_types type on type.id = shop.partner_type_id cross join origin left join lateral (select round(avg(rating)::numeric, 1) average_rating, count(*) review_count from shop_reviews where shop_id = shop.id) reviews on true
  where shop.is_published and shop.latitude is not null and st_dwithin(st_setsrid(st_makepoint(shop.longitude, shop.latitude), 4326)::geography, origin.point, radius_miles * 1609.344) and (partner_type_filter is null or shop.partner_type_id = partner_type_filter) and (capability_filter is null or exists (select 1 from partner_capabilities assigned where assigned.shop_id = shop.id and assigned.capability_id = capability_filter)) and ((vehicle_make is null and vehicle_model is null and vehicle_year is null) or not exists (select 1 from shop_vehicles supported where supported.shop_id = shop.id) or exists (select 1 from shop_vehicles supported join vehicle_catalog vehicle on vehicle.id = supported.vehicle_id where supported.shop_id = shop.id and (vehicle_make is null or vehicle.make = vehicle_make) and (vehicle_model is null or vehicle.model = vehicle_model) and (vehicle_year is null or vehicle.model_year = vehicle_year)))
  order by st_distance(st_setsrid(st_makepoint(shop.longitude, shop.latitude), 4326)::geography, origin.point), shop.id limit result_limit offset result_offset;
end; $$;

create function public.shops_by_location(location_query text, vehicle_make text default null, vehicle_model text default null, vehicle_year integer default null, capability_filter uuid default null, partner_type_filter uuid default null, result_limit integer default 50, result_offset integer default 0)
returns table (id uuid, name text, city text, state text, distance_miles numeric, description text, address text, website text, phone text, email text, hours text, service_territory text, partner_type text, makes text[], models text[], model_years integer[], services text[], certifications text[], average_rating numeric, review_count bigint)
language plpgsql stable security definer set search_path = public as $$
declare normalized_query text;
begin
  normalized_query := regexp_replace(lower(trim(coalesce(location_query, ''))), '[^a-z0-9]+', ' ', 'g');
  if normalized_query = '' or length(location_query) > 120 then raise exception 'Location search is invalid' using errcode = '22023'; end if;
  if result_limit is null or result_limit not between 1 and 100 or result_offset is null or result_offset not between 0 and 10000 then raise exception 'Pagination is outside the allowed range' using errcode = '22023'; end if;
  if length(coalesce(vehicle_make, '')) > 120 or length(coalesce(vehicle_model, '')) > 120 or (vehicle_year is not null and vehicle_year not between 1886 and 2100) then raise exception 'Directory filters are invalid' using errcode = '22023'; end if;

  -- Manual searches use directory location fields, not a global-radius map query.
  return query with origin as (select st_setsrid(st_makepoint(0, 0), 4326)::geography as point)
  select shop.id, shop.name, shop.city, shop.state, round((st_distance(st_setsrid(st_makepoint(shop.longitude, shop.latitude), 4326)::geography, origin.point) / 1609.344)::numeric, 1), shop.description, shop.address, shop.website, shop.phone, shop.email, shop.hours, shop.service_territory, type.name,
    coalesce((select array_agg(distinct vehicle.make order by vehicle.make) from shop_vehicles supported join vehicle_catalog vehicle on vehicle.id = supported.vehicle_id where supported.shop_id = shop.id), '{}'), coalesce((select array_agg(distinct vehicle.model order by vehicle.model) from shop_vehicles supported join vehicle_catalog vehicle on vehicle.id = supported.vehicle_id where supported.shop_id = shop.id), '{}'), coalesce((select array_agg(distinct vehicle.model_year order by vehicle.model_year) from shop_vehicles supported join vehicle_catalog vehicle on vehicle.id = supported.vehicle_id where supported.shop_id = shop.id), '{}'), coalesce((select array_agg(capability.name order by capability.name) from partner_capabilities assigned join service_capabilities capability on capability.id = assigned.capability_id and capability.active where assigned.shop_id = shop.id), '{}'), coalesce((select array_agg(certification.name order by certification.name) from shop_certifications assigned join certifications certification on certification.id = assigned.certification_id and certification.is_active where assigned.shop_id = shop.id), '{}'), reviews.average_rating, coalesce(reviews.review_count, 0)
  from shops shop join partner_types type on type.id = shop.partner_type_id cross join origin left join lateral (select round(avg(rating)::numeric, 1) average_rating, count(*) review_count from shop_reviews where shop_id = shop.id) reviews on true
  where shop.is_published and shop.latitude is not null and regexp_replace(lower(concat_ws(' ', shop.city, shop.state)), '[^a-z0-9]+', ' ', 'g') like '%' || normalized_query || '%' and (partner_type_filter is null or shop.partner_type_id = partner_type_filter) and (capability_filter is null or exists (select 1 from partner_capabilities assigned where assigned.shop_id = shop.id and assigned.capability_id = capability_filter)) and ((vehicle_make is null and vehicle_model is null and vehicle_year is null) or not exists (select 1 from shop_vehicles supported where supported.shop_id = shop.id) or exists (select 1 from shop_vehicles supported join vehicle_catalog vehicle on vehicle.id = supported.vehicle_id where supported.shop_id = shop.id and (vehicle_make is null or vehicle.make = vehicle_make) and (vehicle_model is null or vehicle.model = vehicle_model) and (vehicle_year is null or vehicle.model_year = vehicle_year)))
  order by shop.name, shop.id limit result_limit offset result_offset;
end; $$;

revoke all on function public.nearby_shops(double precision, double precision, integer, text, text, integer, uuid, uuid, integer, integer) from public;
revoke all on function public.shops_by_location(text, text, text, integer, uuid, uuid, integer, integer) from public;
grant execute on function public.nearby_shops(double precision, double precision, integer, text, text, integer, uuid, uuid, integer, integer) to anon, authenticated;
grant execute on function public.shops_by_location(text, text, text, integer, uuid, uuid, integer, integer) to anon, authenticated;
notify pgrst, 'reload schema';
